"""Portable development schema used by SQLite and as a runtime safety net."""
SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS start_prediction_models (model_version TEXT PRIMARY KEY, component TEXT NOT NULL, model_kind TEXT NOT NULL, training_start TEXT, training_end TEXT, feature_names TEXT NOT NULL DEFAULT '[]', parameters TEXT NOT NULL DEFAULT '{}', metrics TEXT NOT NULL DEFAULT '{}', artifact_uri TEXT, is_active INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS race_start_predictions (prediction_id INTEGER PRIMARY KEY AUTOINCREMENT, race_id TEXT NOT NULL, prediction_stage TEXT NOT NULL DEFAULT 'post_exhibition', model_bundle_version TEXT NOT NULL, predicted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, feature_cutoff_at TEXT NOT NULL, input_snapshot TEXT NOT NULL, primary_attack_boat INTEGER, primary_attack_style TEXT, first_mark_boat INTEGER, first_mark_probability REAL, predicted_kimarite TEXT, kimarite_probability REAL, confidence REAL NOT NULL, reasons TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'predicted', evaluated_at TEXT, UNIQUE (race_id, prediction_stage, model_bundle_version));
CREATE TABLE IF NOT EXISTS race_start_prediction_boats (prediction_id INTEGER NOT NULL, boat_number INTEGER NOT NULL, predicted_st REAL NOT NULL, predicted_st_sigma REAL NOT NULL, predicted_start_rank INTEGER NOT NULL, start_top_probability REAL NOT NULL, first_probability REAL NOT NULL, second_probability REAL NOT NULL, third_probability REAL NOT NULL, attack_probability REAL NOT NULL, attack_style TEXT, reasons TEXT NOT NULL DEFAULT '[]', PRIMARY KEY (prediction_id, boat_number));
CREATE TABLE IF NOT EXISTS race_start_prediction_scenarios (prediction_id INTEGER NOT NULL, scenario_kind TEXT NOT NULL, scenario_key TEXT NOT NULL, rank INTEGER NOT NULL, probability REAL NOT NULL, payload TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (prediction_id, scenario_kind, scenario_key));
CREATE TABLE IF NOT EXISTS race_start_prediction_evaluations (prediction_id INTEGER PRIMARY KEY, evaluated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, actual_first_boat INTEGER, actual_kimarite TEXT, actual_start_top_boat INTEGER, st_mae REAL, st_rmse REAL, st_mean_error REAL, start_top_hit INTEGER, start_top2_hit INTEGER, first_mark_hit INTEGER, kimarite_hit INTEGER, winner_hit INTEGER, trifecta_top3_hit INTEGER, trifecta_top5_hit INTEGER, trifecta_top10_hit INTEGER, log_loss REAL, brier_score REAL, error_categories TEXT NOT NULL DEFAULT '[]', actual_snapshot TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS start_prediction_metrics_daily (metric_date TEXT NOT NULL, model_bundle_version TEXT NOT NULL, stadium_number INTEGER NOT NULL DEFAULT 0, race_grade_number INTEGER NOT NULL DEFAULT 0, prediction_count INTEGER NOT NULL, evaluated_count INTEGER NOT NULL, st_mae REAL, st_rmse REAL, start_top_accuracy REAL, winner_accuracy REAL, kimarite_accuracy REAL, trifecta_top10_accuracy REAL, roi REAL, payload TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (metric_date, model_bundle_version, stadium_number, race_grade_number));
CREATE TABLE IF NOT EXISTS derived_start_stats (race_id TEXT NOT NULL, boat_number INTEGER NOT NULL, derived_avg_start_timing_180d REAL, derived_start_count_180d INTEGER NOT NULL DEFAULT 0, derived_avg_start_timing_12 REAL, derived_start_count_12 INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (race_id, boat_number));
CREATE INDEX IF NOT EXISTS idx_start_predictions_race ON race_start_predictions(race_id, predicted_at);
CREATE INDEX IF NOT EXISTS idx_start_predictions_cutoff ON race_start_predictions(feature_cutoff_at);
CREATE INDEX IF NOT EXISTS idx_start_evaluations_date ON race_start_prediction_evaluations(evaluated_at);
CREATE INDEX IF NOT EXISTS idx_derived_start_stats_race ON derived_start_stats(race_id);
"""
